// Store a constant table in flash (not SRAM) with PROGMEM
const PROGMEM uint8_t LOOKUP[16] = {0,1,4,9,16,25,36,49,64,81,100,121,144,169,196,225};

// Read EEPROM — persistent config
void loadConfig() {
  byte deviceId = EEPROM.read(0);  // address 0
  if (deviceId == 0xFF) {          // 0xFF = unprogrammed
    deviceId = 42;
    EEPROM.write(0, deviceId);     // write once
  }
  Serial.print("Device ID: "); Serial.println(deviceId);
}

// Check free SRAM
int freeMemory() {
  extern int __heap_start, *__brkval;
  int v;
  return (int)&v - (__brkval == 0 ? (int)&__heap_start : (int)__brkval);
}

void setup() {
  Serial.begin(115200);
  loadConfig();
  Serial.print("Free SRAM: "); Serial.println(freeMemory());
}

volatile bool buttonPressed = false;  // volatile: modified in ISR

// ISR — keep it SHORT, no Serial, no delay
void IRAM_ATTR onButtonPress() {
  buttonPressed = true;  // just set a flag
}

void setup() {
  Serial.begin(115200);
  pinMode(2, INPUT_PULLUP);
  // Attach interrupt: pin 2, ISR, trigger on FALLING edge
  attachInterrupt(digitalPinToInterrupt(2), onButtonPress, FALLING);
}

void loop() {
  if (buttonPressed) {
    buttonPressed = false;        // clear flag
    Serial.println("Button pressed!");
  }
  // Other work happens here uninterrupted
}
